{"command": "cd /workspace/dabstep-payments-10/inputs && python3 -c "
import csv,collections,datetime
v=collections.defaultdict(float); fv=collections.defaultdict(float)
for r in csv.DictReader(open('payments.csv')):
    if r['merchant']!='Belles_cookbook_store': continue
    if r['is_refused_by_adyen']=='True': continue
    mo=(datetime.date(2023,1,1)+datetime.timedelta(days=int(r['day_of_year'])-1)).month
    v[mo]+=float(r['eur_amount'])
    if r['has_fraudulent_dispute']=='True': fv[mo]+=float(r['eur_amount'])
for mo in (1,3): print(mo, round(v[mo],2), round(100*fv[mo]/v[mo],3))
print('refused frac', sum(1 for r in csv.DictReader(open('payments.csv')) if r['merchant']=='Belles_cookbook_store' and r['is_refused_by_adyen']=='True'))
"", "description": "Check volume excluding refused"}

